<script setup lang="ts">
import { computed,h,onMounted,reactive,ref } from 'vue';
import { NButton,NPopconfirm,NSpace,NTag } from 'naive-ui';import type { DataTableColumns } from 'naive-ui';
import NoticeUserSelect from '@/components/notice-user-select.vue';
import { request } from '@/service/request';
import ImageUpload from '@/components/image-upload/index.vue';
import { createNotice,deleteNotice,fetchNoticeCategories,fetchNoticeDetail,fetchNotices,fetchPostList,unpublishNotice,updateNotice } from '@/service/api';
defineOptions({name:'NoticeManage'});
const categories=ref<Api.P3.Category[]>([]),rows=ref<Api.P3.Notice[]>([]),loading=ref(false),drawer=ref(false),saving=ref(false),editing=ref(false),postLoading=ref(false),pushAvailable=ref(false);
const total=ref(0);const query=reactive<Api.P3.NoticeQuery>({pageNum:1,pageSize:10});const filters=reactive({categoryId:null as number|null,status:null as number|null});
const form=reactive({id:0,title:'',categoryId:null as number|null,postId:null as number|null,status:0,audienceType:'all' as 'all'|'users',recipientUserIds:[] as (string|number)[],pushEnabled:false,blocks:[] as Api.P3.Block[]});
const currentCategory=computed(()=>categories.value.find(x=>x.id===form.categoryId));
const publishedEdit=computed(()=>editing.value&&form.status===1);
const effectiveAudience=computed(()=>publishedEdit.value?form.audienceType:currentCategory.value?.recipientPolicy==='choose'?form.audienceType:currentCategory.value?.recipientPolicy==='users'?'users':'all');
const effectiveUsers=computed(()=>publishedEdit.value||currentCategory.value?.recipientPolicy!=='users'?form.recipientUserIds:currentCategory.value.recipientUserIds);
const postOptions=ref<{label:string;value:number}[]>([]);const categoryOptions=computed(()=>categories.value.filter(x=>x.enabled).map(x=>({label:x.name,value:x.id})));
async function load(){loading.value=true;try{const r=await fetchNotices({...query,categoryId:filters.categoryId??undefined,status:filters.status??undefined});if(r.data){rows.value=r.data.records;total.value=r.data.total;}}finally{loading.value=false;}}
async function loadCategories(){const r=await fetchNoticeCategories();if(r.data)categories.value=r.data;}
function fresh(){editing.value=false;Object.assign(form,{id:0,title:'',categoryId:categoryOptions.value[0]?.value??null,postId:null,status:0,audienceType:'all' as 'all'|'users',recipientUserIds:[] as (string|number)[],pushEnabled:false,blocks:[]});postOptions.value=[];drawer.value=true;}
async function edit(row:Api.P3.Notice){const r=await fetchNoticeDetail(row.id);if(!r.data)return;editing.value=true;let blocks:Api.P3.Block[]=[];try{blocks=JSON.parse(r.data.blocksJson||String(r.data.blocks||'[]'));}catch{}Object.assign(form,{id:r.data.id,title:r.data.title,categoryId:r.data.categoryId,postId:r.data.postId,status:r.data.status,audienceType:r.data.audienceType||'all',recipientUserIds:r.data.recipientUserIds||[],pushEnabled:r.data.pushEnabled||false,blocks});if(r.data.postId)postOptions.value=[{label:'已关联帖子 #'+r.data.postId,value:r.data.postId}];drawer.value=true;}
function addText(){form.blocks.push({type:'text',text:''});}function addImage(){form.blocks.push({type:'image',url:''});}function move(index:number,offset:number){const next=index+offset;if(next<0||next>=form.blocks.length)return;const [item]=form.blocks.splice(index,1);form.blocks.splice(next,0,item);}
async function save(status:number){if(!form.title.trim()||!form.categoryId){window.$message?.warning('请填写标题并选择分类');return;}if(!form.blocks.length||form.blocks.some(b=>b.type==='text'?!b.text?.trim():!b.url)){window.$message?.warning('正文块不能为空');return;}if(effectiveAudience.value==='users'&&!effectiveUsers.value.length){window.$message?.warning('请选择接收用户');return;}saving.value=true;try{const data={id:form.id||undefined,title:form.title,categoryId:form.categoryId,postId:form.postId,status,audienceType:effectiveAudience.value,recipientUserIds:effectiveUsers.value,pushEnabled:form.pushEnabled,blocks:JSON.stringify(form.blocks)};const r=editing.value?await updateNotice(data):await createNotice(data);if(!r.error){window.$message?.success(status===1?'通知已发布':'草稿已保存');drawer.value=false;await load();}}finally{saving.value=false;}}
async function searchPosts(keyword:string){postLoading.value=true;try{const r=await fetchPostList({pageNum:1,pageSize:20,status:1,keyword:keyword.trim()||undefined});if(r.data)postOptions.value=r.data.records.map(p=>({label:p.title+' (#'+p.id+')',value:Number(p.id)}));}finally{postLoading.value=false;}}
async function state(row:Api.P3.Notice){if(row.status!==1){await edit(row);return;}const r=await unpublishNotice(row.id);if(!r.error){window.$message?.success('已下架');if(drawer.value&&form.id===row.id){form.status=0;}await load();}}
const columns:DataTableColumns<Api.P3.Notice>=[{title:'标题',key:'title',minWidth:240,ellipsis:{tooltip:true}},{title:'分类',key:'categoryName',width:140},{title:'接收范围',key:'audienceType',width:120,render:r=>r.audienceType==='users'?'指定用户':'全体用户'},{title:'系统推送',key:'pushTasks',minWidth:160,render:r=>r.pushTasks?.length?r.pushTasks.map(x=>(pushLabels[x.status]||x.status)+': '+x.count).join(' / '):r.pushEnabled?'暂无目标设备':'未开启'},{title:'状态',key:'status',width:100,render:r=>h(NTag,{type:r.status===1?'success':'warning'},()=>r.status===1?'已发布':'草稿')},{title:'发布时间',key:'publishTime',width:180},{title:'操作',key:'op',width:300,render:r=>h(NSpace,{},()=>[h(NButton,{size:'small',onClick:()=>edit(r)},()=> '编辑'),h(NButton,{size:'small',onClick:()=>state(r)},()=>r.status===1?'下架':'发布'),...(r.pushTasks?.some(x=>x.status==='failed')?[h(NButton,{size:'small',onClick:()=>retryPush(r)},()=> '重试推送')]:[]),h(NPopconfirm,{onPositiveClick:async()=>{const x=await deleteNotice(r.id);if(!x.error)await load();}},{trigger:()=>h(NButton,{size:'small',type:'error'},()=> '删除'),default:()=> '确定删除该通知？'})])}];
onMounted(async()=>{const p=await request<{enabled:boolean}>({url:'/notice/push/config'});pushAvailable.value=p.data?.enabled||false;await loadCategories();await load();});
const pushLabels:Record<string,string>={pending:'待发送',sending:'发送中',accepted:'服务商已受理',failed:'失败',cancelled:'已取消'};
async function retryPush(row:Api.P3.Notice){const r=await request({url:'/notice/push/retry',method:'post',data:{id:row.id}});if(!r.error){window.$message?.success('失败任务已重新排队');await load();}}
</script>
<template>
 <div>
 <NCard title="通知内容" :bordered="false"><template #header-extra><NButton type="primary" @click="fresh">新建通知</NButton></template>
  <NSpace class="mb-16px"><NSelect v-model:value="filters.categoryId" :options="categoryOptions" clearable placeholder="全部分类" class="w-180px" /><NSelect v-model:value="filters.status" :options="[{label:'草稿',value:0},{label:'已发布',value:1}]" clearable placeholder="全部状态" class="w-140px" /><NButton type="primary" @click="query.pageNum=1;load()">查询</NButton></NSpace>
  <NDataTable :columns="columns" :data="rows" :loading="loading" :scroll-x="1280" />
  <div class="mt-16px flex justify-end"><NPagination v-model:page="query.pageNum" v-model:page-size="query.pageSize" :item-count="total" :page-sizes="[10,20,50]" show-size-picker @update:page="load" @update:page-size="query.pageNum=1;load()" /></div>
 </NCard>
 <NDrawer v-model:show="drawer" :width="640"><NDrawerContent :title="editing?'编辑通知':'新建通知'" closable>
  <NForm label-placement="top"><NFormItem label="标题"><NInput v-model:value="form.title" maxlength="100" show-count /></NFormItem><NFormItem label="分类"><NSelect v-model:value="form.categoryId" :options="categoryOptions" :disabled="publishedEdit" /></NFormItem><NFormItem label="接收范围"><NSelect v-if="!publishedEdit && currentCategory?.recipientPolicy==='choose'" v-model:value="form.audienceType" :options="[{label:'全体用户',value:'all'},{label:'指定用户',value:'users'}]" /><NText v-else>{{ effectiveAudience==='users'?'指定用户':'全体用户' }}{{ publishedEdit?'（本次发布范围）':'（分类固定）' }}</NText></NFormItem>
   <NFormItem v-if="effectiveAudience==='users'" label="接收用户"><NoticeUserSelect :value="effectiveUsers" :disabled="publishedEdit || currentCategory?.recipientPolicy==='users'" @update:value="form.recipientUserIds=$event" /></NFormItem>
   <NFormItem label="同步发送系统通知"><NSwitch v-model:value="form.pushEnabled" :disabled="publishedEdit || !pushAvailable" /><NText class="ml-12px" depth="3">{{publishedEdit?'保存内容修改不会重复提醒':pushAvailable?'发布时同步发送 Android 系统通知':'请先在系统推送配置中开启服务'}}</NText></NFormItem>
   <NFormItem label="关联帖子"><NSelect v-model:value="form.postId" :options="postOptions" clearable filterable remote :loading="postLoading" placeholder="输入已发布帖子标题搜索" @search="searchPosts" /><div class="mt-6px text-12px text-gray">关联用于通知的帖子跳转；首页资讯轮播请在帖子管理中单独设置。</div></NFormItem>
   <NFormItem label="正文"><div class="w-full"><div v-for="(block,index) in form.blocks" :key="index" class="mb-12px flex items-start gap-8px rounded-8px border border-gray-200 p-12px"><div class="min-w-0 flex-1"><NInput v-if="block.type==='text'" v-model:value="block.text" type="textarea" autosize maxlength="2000" show-count placeholder="请输入段落" /><ImageUpload v-else v-model="block.url!" /></div><NSpace vertical size="small"><NButton size="tiny" :disabled="index===0" @click="move(index,-1)">上移</NButton><NButton size="tiny" :disabled="index===form.blocks.length-1" @click="move(index,1)">下移</NButton><NButton size="tiny" type="error" @click="form.blocks.splice(index,1)">删除</NButton></NSpace></div><NSpace><NButton @click="addText">添加段落</NButton><NButton @click="addImage">添加图片</NButton></NSpace></div></NFormItem>
  </NForm><template #footer><NSpace justify="end"><NButton v-if="editing&&form.status===1" @click="drawer=false">取消</NButton><NButton v-if="form.status!==1" :loading="saving" @click="save(0)">存草稿</NButton><NButton type="primary" :loading="saving" @click="save(1)">{{editing&&form.status===1?'保存修改':'发布'}}</NButton><NButton v-if="editing&&form.status===1" type="warning" @click="state(rows.find(x=>x.id===form.id)!)">下架</NButton></NSpace></template>
 </NDrawerContent></NDrawer>
 </div>
</template>

